def closest_k_values(root, target, k):
    values = []
    def inorder(node):
        if node:
            inorder(node.left); values.append(node.val); inorder(node.right)
    inorder(root)                                          # flatten to sorted values

    lo, hi = 0, len(values) - k
    while lo < hi:
        mid = (lo + hi) // 2
        if target - values[mid] > values[mid + k] - target:    # left edge farther than right edge dropped
            lo = mid + 1
        else:
            hi = mid
    return values[lo:lo + k]

