import java.util.*;

public class Main {
    static List<Integer> vals = new ArrayList<>();
    static void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left); vals.add(node.val); inorder(node.right);
    }
    static List<Integer> closestKValues(TreeNode root, double target, int k) {
        inorder(root);                                          // flatten to sorted values
        int lo = 0, hi = vals.size() - k;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (target - vals.get(mid) > vals.get(mid + k) - target) lo = mid + 1;
            else hi = mid;
        }
        return vals.subList(lo, lo + k);
    }
}

